/// <summary>
/// The <c>AVARUMSalesTableFrm_SalesLineDS_SalesQtyFld_Extension</c> class  
/// </summary>
/// <remarks>
/// Modified for price recalculation
/// </remarks>
[ExtensionOf(formDataFieldStr(SalesTable, SalesLine, SalesQty))]
final class AVARUMSalesTableFrm_SalesLineDS_SalesQtyFld_Extension
{
}

Method.Source:
/// <summary>
/// Modified
/// </summary>
public void modified()
{
    FormDataObject formDataObject;
    FormDataSource formDataSource;
    SalesLine salesLine;

    formDataObject = Global::any2Object(this) as FormDataObject;
    formDataSource = formDataObject.datasource();

    next modified();

    salesLine = formDataSource.cursor();
    salesLine.setCustomFields_AVA();
    formDataSource.refresh();
}
